    "Tài liệu vật liệu": "Material documents",
    "Tài liệu vật liệu được sử dụng trong quá trình lựa chọn nguồn cung, phát triển sản phẩm, sản xuất mẫu và sản xuất hàng loạt nhằm đảm bảo sử dụng đúng vật liệu đã được phê duyệt.": "Material documentation is used during source selection, product development, prototyping and mass production to ensure the correct approved materials are used.",
