    "Vietnam Supply Hub là gì?": "What is Vietnam Supply Hub?",
    "Việc quản lý đúng phiên bản giúp giảm sai lệch giữa các nhà máy, hạn chế lỗi sản xuất và đảm bảo tính đồng nhất trên mọi lô hàng.": "Proper version management reduces variations between factories, limits manufacturing errors and ensures uniformity across every batch.",
