    "Tài liệu vật liệu": "重要書類",
    "Tài liệu vật liệu được sử dụng trong quá trình lựa chọn nguồn cung, phát triển sản phẩm, sản xuất mẫu và sản xuất hàng loạt nhằm đảm bảo sử dụng đúng vật liệu đã được phê duyệt.": "材料に関する文書は、ソースの選択、製品開発、プロトタイピング、および大量生産の際に使用され、承認された正しい材料が使用されていることを確認します。",
    "Tài liệu vật liệu là cơ sở tham chiếu chính thức giúp các bên liên quan sử dụng đúng loại vật liệu đã được phê duyệt, đồng thời duy trì tính nhất quán giữa mẫu phát triển, sản xuất hàng loạt và các lô hàng xuất khẩu.": "材料ドキュメントは、開発サンプル、量産、輸出出荷の間の一貫性を維持しながら、関係者が承認された正しい材料を使用するのに役立つ公式リファレンスです。",
    "Tải tài liệu lên": "書類のアップロード",
