    "GỖ TỰ NHIÊN": "NATURLIGT TRÄ",
    "Gửi kế hoạch tồn kho, nhóm hàng, tần suất xuất hàng hoặc yêu cầu vận hành để ANSLIFE đề xuất phương án lưu kho phù hợp với chuỗi cung ứng của bạn.": "Skicka in lagerplaner, produktgrupper, fraktfrekvens eller driftskrav till ANSLIFE för att föreslå en lagringsplan som passar din leveranskedja.",
    "Gửi tài liệu kỹ thuật cho ANSLIFE": "Skicka in tekniska dokument till ANSLIFE",
