    "Tồn kho đệm (Buffer Inventory)": "Buffertlager",
    "Tồn kho đệm giúp duy trì lượng hàng sẵn có tại Việt Nam, sẵn sàng đáp ứng các lô xuất hàng theo lịch. ANSLIFE quản lý tồn kho hiệu quả để đảm bảo nguồn hàng luôn sẵn sàng theo kế hoạch.": "Buffertlager hjälper till att upprätthålla tillgängliga varor i Vietnam, redo att möta schemalagda leveranser. ANSLIFE hanterar effektivt lager för att säkerställa att varor alltid är tillgängliga som planerat.",
