    "Bản vẽ kỹ thuật được lưu trữ cùng các tài liệu tham chiếu để hình thành hệ thống chuẩn thống nhất cho từng buyer.": "Les dessins techniques sont stockés avec les documents de référence pour former un système standard unifié pour chaque acheteur.",
    "Bản vẽ kỹ thuật là tài liệu tham chiếu chính thức trong suốt quá trình phát triển sản phẩm, sản xuất, kiểm tra chất lượng, đóng gói và xuất khẩu.": "Les dessins techniques sont les documents de référence officiels tout au long du développement du produit, de sa fabrication, de son contrôle qualité, de son emballage et de son exportation.",
