    "Bao gồm plywood, MDF, particle board, veneer panel và các vật liệu kỹ thuật khác được sử dụng trong sản xuất.": "Y compris le contreplaqué, le MDF, les panneaux de particules, les panneaux de placage et autres matériaux d'ingénierie utilisés dans la production.",
    "Bao gồm vải, da, PU, foam, vật liệu đệm và các tài liệu kỹ thuật liên quan đến từng dự án.": "Y compris le tissu, le cuir, le PU, la mousse, les matériaux de rembourrage et les documents techniques liés à chaque projet.",
