    "Cần hỗ trợ chuẩn hóa thông tin và phối hợp hồ sơ xuất khẩu.": "Besoin de soutien pour standardiser les informations et coordonner les documents d’exportation.",
    "Cần hỗ trợ quản lý chứng từ xuất khẩu?": "Besoin d’aide pour gérer les documents d’exportation ?",
