    "Cần lưu kho vật liệu hoặc cấu kiện tại Việt Nam?": "Besoin de stocker des matériaux ou des composants au Vietnam ?",
    "Cần quản lý hồ sơ kỹ thuật, hồ sơ QC và chứng từ thương mại trong thời gian dài.": "Besoin de gérer les dossiers techniques, les dossiers CQ et les documents commerciaux sur une longue période.",
