    "Hạn chế sai khác về chất lượng, màu sắc, hoàn thiện và đóng gói.": "Limiter les variations de qualité, de couleur, de finition et d’emballage.",
    "Hạn chế thiếu hàng trong mùa cao điểm": "Limiter les pénuries de produits en haute saison",
