    "Hàng dự phòng cho các đơn hàng lặp lại": "Stock de sauvegarde pour les commandes répétées",
    "Hàng FCL": "Marchandises FCL",
    "Hàng hóa có thể được lưu trữ dưới dạng thành phẩm, cấu kiện, linh kiện, vật liệu hoặc hàng dự án theo kế hoạch cung ứng của từng đối tác. Giải pháp này đặc biệt phù hợp với các buyer cần xuất hàng định kỳ, duy trì tồn kho đệm hoặc vận hành nhiều nhà cung cấp tại Việt Nam.": "Les marchandises peuvent être stockées sous forme de produits finis, de composants, de composants, de matériaux ou de biens de projet selon le plan d'approvisionnement de chaque partenaire. Cette solution est particulièrement adaptée aux acheteurs qui doivent expédier des marchandises périodiquement, maintenir un inventaire tampon ou exploiter plusieurs fournisseurs au Vietnam.",
    "Hàng hóa được lưu kho phục vụ cho các đơn hàng đã xác nhận hoặc kế hoạch giao hàng cụ thể.": "Les marchandises sont stockées pour des commandes confirmées ou des plans de livraison spécifiques.",
    "Hàng hóa luôn sẵn sàng tại Việt Nam để điều phối và xuất khẩu.": "Les marchandises sont toujours disponibles au Vietnam pour la coordination et l'exportation.",
    "Hàng LCL": "Marchandises LCL",
    "Hàng mẫu": "Exemples de marchandises",
    "Hàng nguyên container": "Marchandises en conteneur complet",
    "Hàng từ nhiều nhà máy khác nhau": "Marchandises provenant de nombreuses usines différentes",
    "Hệ thống chất lượng được triển khai xuyên suốt từ giai đoạn đánh giá vật liệu, kiểm soát sản xuất, kiểm tra hoàn thiện, đóng gói và giao hàng, giúp giảm thiểu rủi ro và duy trì tính đồng nhất giữa các lô hàng.": "Le système qualité est mis en œuvre tout au long des étapes d'évaluation des matériaux, de contrôle de la production, d'inspection de finition, d'emballage et de livraison, contribuant ainsi à minimiser les risques et à maintenir l'uniformité entre les expéditions.",
