    "Sau khi tập kết tại kho, hàng hóa sẽ được kiểm tra, phân loại và tổ chức xuất khẩu theo kế hoạch của buyer.": "Après collecte à l'entrepôt, les marchandises seront inspectées, classées et exportées selon le plan de l'acheteur.",
