    "Tồn kho đệm (Buffer Inventory)": "Inventaire tampon",
    "Tồn kho đệm giúp duy trì lượng hàng sẵn có tại Việt Nam, sẵn sàng đáp ứng các lô xuất hàng theo lịch. ANSLIFE quản lý tồn kho hiệu quả để đảm bảo nguồn hàng luôn sẵn sàng theo kế hoạch.": "L'inventaire tampon permet de maintenir les marchandises disponibles au Vietnam, prêtes à répondre aux expéditions programmées. ANSLIFE gère efficacement les stocks pour garantir que les marchandises sont toujours disponibles comme prévu.",
