    "Vietnam Supply Hub là gì?": "Qu’est-ce que le centre d’approvisionnement du Vietnam ?",
    "Việc quản lý đúng phiên bản giúp giảm sai lệch giữa các nhà máy, hạn chế lỗi sản xuất và đảm bảo tính đồng nhất trên mọi lô hàng.": "Une bonne gestion des versions réduit les variations entre les usines, limite les erreurs de fabrication et garantit l’uniformité de chaque lot.",
