    "BẢN VẼ ĐÓNG GÓI": "УПАКОВОЧНЫЕ ЧЕРТЕЖИ",
    "Bản vẽ kỹ thuật": "Технические чертежи",
    "Bản vẽ kỹ thuật được lưu trữ cùng các tài liệu tham chiếu để hình thành hệ thống chuẩn thống nhất cho từng buyer.": "Технические чертежи хранятся вместе со справочной документацией, образуя единую стандартную систему для каждого покупателя.",
    "Bản vẽ kỹ thuật là tài liệu tham chiếu chính thức trong suốt quá trình phát triển sản phẩm, sản xuất, kiểm tra chất lượng, đóng gói và xuất khẩu.": "Технические чертежи являются официальными справочными документами при разработке, производстве, контроле качества, упаковке и экспорте продукции.",
    "Bản vẽ lắp ráp": "Сборочный чертеж",
