    "Banner bản vẽ kỹ thuật trong phòng mẫu chuẩn đối tác": "Баннер с техническими чертежами в стандартной комнате для образцов партнера",
    "Banner checklist QC trong phòng mẫu chuẩn đối tác": "Баннер контрольного списка контроля качества в стандартной комнате для образцов партнера",
    "Banner mẫu cấu kiện trong phòng mẫu chuẩn đối tác": "Баннеры с образцами компонентов в стандартной комнате для образцов партнеров",
    "Banner mẫu sản phẩm đã duyệt trong phòng mẫu chuẩn đối tác": "Баннеры с утвержденными образцами продукции в стандартной комнате для образцов партнеров",
    "Banner mẫu vật liệu tham chiếu trong phòng mẫu chuẩn đối tác": "Баннер с образцом справочного материала в стандартной комнате для образцов партнера",
    "Banner tiêu chuẩn đóng gói trong phòng mẫu chuẩn đối tác": "Стандартные баннеры упаковываются в стандартной комнате для образцов нашего партнера.",
    "Banner tổng quan hệ thống chất lượng": "Баннер с обзором системы качества",
