    "Bao gồm plywood, MDF, particle board, veneer panel và các vật liệu kỹ thuật khác được sử dụng trong sản xuất.": "В том числе фанера, МДФ, ДСП, шпон и другие конструкционные материалы, используемые в производстве.",
    "Bao gồm vải, da, PU, foam, vật liệu đệm và các tài liệu kỹ thuật liên quan đến từng dự án.": "Включая ткань, кожу, полиуретан, пену, амортизирующие материалы и техническую документацию, относящуюся к каждому проекту.",
    "Bao gồm:": "Включает:",
    "Bảo vệ sản phẩm trong suốt quá trình lưu kho, vận chuyển và giao nhận quốc tế.": "Защитите продукцию во время международного хранения, транспортировки и доставки.",
