    "Tài liệu vật liệu là cơ sở tham chiếu chính thức giúp các bên liên quan sử dụng đúng loại vật liệu đã được phê duyệt, đồng thời duy trì tính nhất quán giữa mẫu phát triển, sản xuất hàng loạt và các lô hàng xuất khẩu.": "Документ о материале представляет собой официальный справочник, который помогает заинтересованным сторонам использовать правильные утвержденные материалы, сохраняя при этом согласованность между образцами разработки, массовым производством и экспортными поставками.",
