    "Vietnam Supply Hub là gì?": "Что такое Вьетнамский центр поставок?",
    "Việc quản lý đúng phiên bản giúp giảm sai lệch giữa các nhà máy, hạn chế lỗi sản xuất và đảm bảo tính đồng nhất trên mọi lô hàng.": "Правильное управление версиями уменьшает различия между заводами, ограничивает производственные ошибки и обеспечивает единообразие каждой партии.",
