    "Tài liệu vật liệu": "Documentos materiales",
    "Tài liệu vật liệu được sử dụng trong quá trình lựa chọn nguồn cung, phát triển sản phẩm, sản xuất mẫu và sản xuất hàng loạt nhằm đảm bảo sử dụng đúng vật liệu đã được phê duyệt.": "La documentación del material se utiliza durante la selección de fuentes, el desarrollo de productos, la creación de prototipos y la producción en masa para garantizar que se utilicen los materiales aprobados correctos.",
    "Tài liệu vật liệu là cơ sở tham chiếu chính thức giúp các bên liên quan sử dụng đúng loại vật liệu đã được phê duyệt, đồng thời duy trì tính nhất quán giữa mẫu phát triển, sản xuất hàng loạt và các lô hàng xuất khẩu.": "El documento de materiales es una referencia oficial que ayuda a las partes interesadas a utilizar los materiales aprobados correctos, manteniendo al mismo tiempo la coherencia entre las muestras de desarrollo, la producción en masa y los envíos de exportación.",
