    "Vietnam Supply Hub là gì?": "¿Qué es el centro de suministro de Vietnam?",
    "Việc quản lý đúng phiên bản giúp giảm sai lệch giữa các nhà máy, hạn chế lỗi sản xuất và đảm bảo tính đồng nhất trên mọi lô hàng.": "La gestión adecuada de versiones reduce las variaciones entre fábricas, limita los errores de fabricación y garantiza la uniformidad en cada lote.",
